using System.Collections.Generic;

namespace AcEvoFfbTuner.Help;

/// <summary>
/// The complete built-in Help guide content, in plain language for any user.
/// Articles are ordered logically: first run → each app page in sidebar order →
/// settings → troubleshooting. Every slider describes both what it does and the
/// "feel" it produces, so users can tune by hand and by feel.
/// </summary>
public static class HelpCatalog
{
    public static IReadOnlyList<HelpArticle> Articles { get; } = Build();

    private static HelpParagraph P(string text) => new(text);
    private static HelpBullets B(params string[] items) => new(items);
    private static HelpNote Note(string title, string text) => new(title, text);
    private static HelpSliderRow Hsl(string name, string range, string feel) => new(name, range, feel);
    private static HelpSection S(string heading, params HelpBlock[] blocks)
    {
        var s = new HelpSection { Heading = heading };
        s.Blocks.AddRange(blocks);
        return s;
    }

    private static HelpArticle A(string title, string subtitle, string[] keywords, params HelpSection[] sections)
    {
        var article = new HelpArticle
        {
            Title = title,
            Subtitle = subtitle,
            Keywords = keywords
        };
        article.Sections.AddRange(sections);

        var sb = new System.Text.StringBuilder();
        sb.Append(title).Append(' ').Append(subtitle).Append(' ');
        foreach (var k in keywords) sb.Append(k).Append(' ');
        foreach (var s in sections)
        {
            sb.Append(s.Heading).Append(' ');
            foreach (var b in s.Blocks)
            {
                switch (b)
                {
                    case HelpParagraph p: sb.Append(p.Text).Append(' '); break;
                    case HelpBullets bl:
                        foreach (var i in bl.Items) sb.Append(i).Append(' ');
                        break;
                    case HelpNote n: sb.Append(n.Title).Append(' ').Append(n.Text).Append(' '); break;
                    case HelpSliderRow sl:
                        sb.Append(sl.Name).Append(' ').Append(sl.Range).Append(' ').Append(sl.Feel).Append(' ');
                        break;
                }
            }
        }
        article.SearchText = sb.ToString().ToLowerInvariant();
        return article;
    }

