                    Hsl("Engine Off Damping", "0 – 0.5", "Viscous damping with the engine off — absorbs motor inertia so the wheel does not buzz. Default 0.15."),
                    Hsl("Engine On Damping", "0 – 0.2", "Viscous damping with the engine running — much lower, simulating power assist. Default 0.02."),
                    Hsl("Active Decay", "0.5 – 1", "How fast the elastic displacement fades while you are turning. Lower = faster decay = more stable on strong wheels. 0.92 default; try 0.5–0.8 on very strong wheelbases if it feels springy."),
                    Hsl("Return Decay", "0.1 – 0.99", "How fast the spring pull-back fades. Lower = quicker kill of oscillation when the wheel returns to centre. 0.65 default; 0.1–0.4 on strong bases."),
                    Hsl("Output Smoothing", "0.05 – 1", "Smooths the force output. 0.35 = smooth but responsive; 1.0 = no smoothing. Reduces the notchy feel from the game's discrete steering steps.")),
